group_recording_rules.expr:
(
  label_replace(
    (
      oie_instance_cpu_vcpu_percent{job="openstack-instance-exporter"}
      and on (job, instance, instance_uuid) oie:resource_axis_current{axis="cpu"}
    ),
    "signal", "cpu_percent", "__name__", ".*"
  )
)
or (
  label_replace(
    (
      rate(oie_instance_mem_major_faults_total{job="openstack-instance-exporter"}[5m])
      and oie_instance_mem_major_faults_total{job="openstack-instance-exporter"}
      and on (job, instance, instance_uuid) oie:resource_axis_current{axis="mem"}
    ),
    "signal", "major_faults_per_second", "__name__", ".*"
  )
)
or (
  label_replace(
    (
      (oie_instance_disk_read_iops{job="openstack-instance-exporter"} + oie_instance_disk_write_iops{job="openstack-instance-exporter"})
      and on (job, instance, instance_uuid) oie:resource_axis_current{axis="disk"}
    ),
    "signal", "disk_iops", "__name__", ".*"
  )
)
or (
  label_replace(
    (
      (rate(oie_instance_disk_read_gib_total{job="openstack-instance-exporter"}[5m]) + rate(oie_instance_disk_write_gib_total{job="openstack-instance-exporter"}[5m])) * 1073741824
      and oie_instance_disk_read_gib_total{job="openstack-instance-exporter"}
      and oie_instance_disk_write_gib_total{job="openstack-instance-exporter"}
      and on (job, instance, instance_uuid) oie:resource_axis_current{axis="disk"}
    ),
    "signal", "disk_bytes_per_second", "__name__", ".*"
  )
)
or (
  label_replace(
    (
      oie_instance_conntrack_ip_flows{job="openstack-instance-exporter"}
      and on (job, instance, instance_uuid) oie:network_current
    ),
    "signal", "conntrack_flows", "__name__", ".*"
  )
)
or (
  label_replace(
    (
      rate(oie_instance_net_rx_packets_total{job="openstack-instance-exporter"}[2m])
      and oie_instance_net_rx_packets_total{job="openstack-instance-exporter"}
      and on (job, instance, instance_uuid) oie:resource_axis_current{axis="net"}
    ),
    "signal", "rx_packets_per_second", "__name__", ".*"
  )
)
or (
  label_replace(
    (
      rate(oie_instance_net_rx_gib_total{job="openstack-instance-exporter"}[2m]) * 1073741824
      and oie_instance_net_rx_gib_total{job="openstack-instance-exporter"}
      and on (job, instance, instance_uuid) oie:resource_axis_current{axis="net"}
    ),
    "signal", "rx_bytes_per_second", "__name__", ".*"
  )
)
or (
  label_replace(
    (
      rate(oie_instance_net_tx_packets_total{job="openstack-instance-exporter"}[2m])
      and oie_instance_net_tx_packets_total{job="openstack-instance-exporter"}
      and on (job, instance, instance_uuid) oie:resource_axis_current{axis="net"}
    ),
    "signal", "tx_packets_per_second", "__name__", ".*"
  )
)
or (
  label_replace(
    (
      rate(oie_instance_net_tx_gib_total{job="openstack-instance-exporter"}[2m]) * 1073741824
      and oie_instance_net_tx_gib_total{job="openstack-instance-exporter"}
      and on (job, instance, instance_uuid) oie:resource_axis_current{axis="net"}
    ),
    "signal", "tx_bytes_per_second", "__name__", ".*"
  )
)
or (
  label_replace(
    (
      oie_instance_inbound_unique_remotes{job="openstack-instance-exporter"}
      and on (job, instance, instance_uuid) oie:network_current
    ),
    "signal", "inbound_remotes", "__name__", ".*"
  )
)
or (
  label_replace(
    (
      oie_instance_outbound_unique_remotes{job="openstack-instance-exporter"}
      and on (job, instance, instance_uuid) oie:network_current
    ),
    "signal", "outbound_remotes", "__name__", ".*"
  )
)

rate(oie_instance_disk_read_seconds_total{job="openstack-instance-exporter"}[5m]) / rate(oie_instance_disk_read_requests_total{job="openstack-instance-exporter"}[5m])
and (increase(oie_instance_disk_read_requests_total{job="openstack-instance-exporter"}[5m]) >= 60)
and oie_instance_disk_read_seconds_total{job="openstack-instance-exporter"}
and oie_instance_disk_read_requests_total{job="openstack-instance-exporter"}
and (count_over_time(oie_instance_disk_read_seconds_total{job="openstack-instance-exporter"}[5m]) == count_over_time(oie_instance_disk_read_requests_total{job="openstack-instance-exporter"}[5m]))
and on (job, instance, instance_uuid) oie:resource_axis_current{axis="disk"}

